-- Revised 2024 KICD Grade 4 Indigenous Languages design: 9 themes,
-- 3 official strands and 27 two-lesson thematic sub-strands, 6-lesson cross-strand showcase.
-- 60 lessons are the KICD design total, NOT an authorized weekly allocation.
-- 84 independently authored VibeSchool outcomes are ENGLISH editorial guidance;
-- each local language requires authentic language/orthography review before publication.
-- This migration preserves the existing 10 Grade 4 Indigenous Languages legacy strands,
-- all teacher Scheme lessons, timetables, attendance and historical outcomes.
-- authorization-test: public.grade4_indigenous_reader_bindings
begin;
create table if not exists public.grade4_indigenous_reader_bindings (
 source_ref text primary key check(source_ref like 'VS-CUR-G04-IL-2026#%'),
 sub_strand_id uuid not null unique references public.cbc_strands(id) on delete restrict,
 source_url text not null,
 source_version text not null,
 key_inquiry_questions text[] not null default '{}',
 suggested_experiences text[] not null default '{}',
 status text not null default 'active' check(status in ('active','archived')),
 localization_status text not null default 'language_adaptation_required'
  check(localization_status in ('language_adaptation_required','language_reviewed')),
 created_at timestamptz not null default now()
);
alter table public.grade4_indigenous_reader_bindings enable row level security;
revoke all on public.grade4_indigenous_reader_bindings from public,anon,authenticated;
grant select on public.grade4_indigenous_reader_bindings to authenticated;
drop policy if exists grade4_indigenous_bindings_read on public.grade4_indigenous_reader_bindings;
create policy grade4_indigenous_bindings_read on public.grade4_indigenous_reader_bindings
 for select to authenticated using(status='active');

create temporary table _vs_g4_il_catalog(source_ref text primary key,unit jsonb not null) on commit drop;
insert into _vs_g4_il_catalog(source_ref,unit)
select 'VS-CUR-G04-IL-2026#'||(unit->>'id'),unit
from jsonb_array_elements($vs_g4_il$[{"id":"01-LS","theme":1,"themeTitle":"Cultural Foods","sourcePage":1,"strand":"Listening and Speaking","title":"Cultural Foods: Attentive Listening","focus":"Attentive Listening","focusDetail":"Songs, singular and plural nouns, responding to instructions","lessons":2,"crossStrand":false,"outcomes":["Listen to songs with singular and plural food nouns in the selected indigenous language and identify two accurate details without guessing.","Use songs, singular and plural nouns, responding to instructions in a culturally appropriate response about food preparation, family recipes and respectful sharing of meals, with guidance from a fluent speaker.","Present a short spoken exchange and respond respectfully to another speaker's question or correction."],"inquiry":["What makes a listener understand a message about cultural foods?","How do experienced speakers in our community express attentive listening naturally?"],"experiences":["A fluent community-language speaker models songs with singular and plural food nouns; pupils describe the central message before asking one question.","Pairs rehearse a short exchange using language-specific vocabulary confirmed by the teacher and compare expression, tone and courtesy."],"resources":"Fluent community-language recording, picture prompts and pair-speaking cards.","assessment":"Teacher observes attentive recall, authentic local-language vocabulary and respectful oral interaction, using a simple three-point checklist.","competencies":"Communication and collaboration; creativity; critical thinking; self-efficacy; cultural identity; digital literacy where permitted.","reviewStatus":"language_adaptation_required"},{"id":"01-RD","theme":1,"themeTitle":"Cultural Foods","sourcePage":1,"strand":"Reading","title":"Cultural Foods: Reading for Information","focus":"Reading for Information","focusDetail":"Vocabulary, food names, singular and plural forms","lessons":2,"crossStrand":false,"outcomes":["Read short descriptions of local dishes and their ingredients in the selected indigenous language, attending to vocabulary, food names, singular and plural forms.","Locate and explain two details from the reading and support an interpretation with words from the text.","Explain a new word, proverb or expression through context or confirmation with a fluent language user."],"inquiry":["How can a reader understand cultural foods from words and surrounding clues?","What does the text reveal about how this community uses language?"],"experiences":["Use a locally verified short text about food preparation, family recipes and respectful sharing of meals; learners mark familiar words, predict meaning and reread for accuracy.","Pairs discuss a comprehension question and practise correct pacing or interpretation with a fluent speaker's feedback."],"resources":"Original or licensed local-language passage, bilingual picture clues and reader's notebook.","assessment":"Reading aloud or assisted reading plus two text-based questions and a short explanation of a locally verified expression.","competencies":"Communication and collaboration; creativity; critical thinking; self-efficacy; cultural identity; digital literacy where permitted.","reviewStatus":"language_adaptation_required"},{"id":"01-WR","theme":1,"themeTitle":"Cultural Foods","sourcePage":1,"strand":"Writing","title":"Cultural Foods: Handwriting","focus":"Handwriting","focusDetail":"Letter formation, neatness and legible sentences","lessons":2,"crossStrand":false,"outcomes":["Recognise the purpose and accepted spelling or writing conventions for handwriting in the chosen indigenous language.","Produce an original, age-appropriate written response about food preparation, family recipes and respectful sharing of meals that uses letter formation, neatness and legible sentences.","Revise for local-language spelling, readable organisation and correct meaning with feedback from a fluent speaker."],"inquiry":["How can writing about