g","focus":"Attentive Listening","focusDetail":"Polite telephone expressions and descriptive adjectives","lessons":2,"crossStrand":false,"outcomes":["Listen to a polite telephone conversation about arranging a school activity in the selected indigenous language and identify two accurate details without guessing.","Use polite telephone expressions and descriptive adjectives in a culturally appropriate response about using communication devices politely and safely, with guidance from a fluent speaker.","Present a short spoken exchange and respond respectfully to another speaker's question or correction."],"inquiry":["What makes a listener understand a message about technology–digital devices?","How do experienced speakers in our community express attentive listening naturally?"],"experiences":["A fluent community-language speaker models a polite telephone conversation about arranging a school activity; pupils describe the central message before asking one question.","Pairs rehearse a short exchange using language-specific vocabulary confirmed by the teacher and compare expression, tone and courtesy."],"resources":"Fluent community-language recording, picture prompts and pair-speaking cards.","assessment":"Teacher observes attentive recall, authentic local-language vocabulary and respectful oral interaction, using a simple three-point checklist.","competencies":"Communication and collaboration; creativity; critical thinking; self-efficacy; cultural identity; digital literacy where permitted.","reviewStatus":"language_adaptation_required"},{"id":"08-RD","theme":8,"themeTitle":"Technology–Digital Devices","sourcePage":43,"strand":"Reading","title":"Technology–Digital Devices: Extensive Reading","focus":"Extensive Reading","focusDetail":"Advertisements, news and descriptive language","lessons":2,"crossStrand":false,"outcomes":["Read a classroom announcement and an age-appropriate advertisement in the selected indigenous language, attending to advertisements, news and descriptive language.","Locate and explain two details from the reading and support an interpretation with words from the text.","Explain a new word, proverb or expression through context or confirmation with a fluent language user."],"inquiry":["How can a reader understand technology–digital devices from words and surrounding clues?","What does the text reveal about how this community uses language?"],"experiences":["Use a locally verified short text about using communication devices politely and safely; learners mark familiar words, predict meaning and reread for accuracy.","Pairs discuss a comprehension question and practise correct pacing or interpretation with a fluent speaker's feedback."],"resources":"Original or licensed local-language passage, bilingual picture clues and reader's notebook.","assessment":"Reading aloud or assisted reading plus two text-based questions and a short explanation of a locally verified expression.","competencies":"Communication and collaboration; creativity; critical thinking; self-efficacy; cultural identity; digital literacy where permitted.","reviewStatus":"language_adaptation_required"},{"id":"08-WR","theme":8,"themeTitle":"Technology–Digital Devices","sourcePage":43,"strand":"Writing","title":"Technology–Digital Devices: Functional Writing: Forms","focus":"Functional Writing: Forms","focusDetail":"Designing and completing sample information forms","lessons":2,"crossStrand":false,"outcomes":["Recognise the purpose and accepted spelling or writing conventions for functional writing: forms in the chosen indigenous language.","Produce an original, age-appropriate written response about using communication devices politely and safely that uses designing and completing sample information forms.","Revise for local-language spelling, readable organisation and correct meaning with feedback from a fluent speaker."],"inquiry":["How can writing about technology–digital devices be made clearer for its intended reader?","Which writing conventions are used by fluent writers of this indigenous language?"],"experiences":["Observe a locally verified writing model about using communication devices politely and safely; sort its useful features and plan a short response.","Draft, exchange careful feedback and revise a final version, following the chosen language's orthography rather than imported English spelling rules."],"resources":"Paper, writing strips and a language-specific, fluent-speaker-checked model.","assessment":"Short written product checked for purpose, clear organisation and language-specific orthography verified by a competent speaker.","competencies":"Communication and collaboration; creativity; critical thinking; self-efficacy; cultural identity; digital literacy where permitted.","reviewStatus":"language_adaptation_required"},{"id":"09-LS","theme":9,"themeTitle":"Leadership","sourcePage":49,"strand":"Listening and Speaking","title":"Leadership: Self-expression","focus":"Self-expression","focusDetail":"Taking turns, polite interruption and verbs","lessons":2,"crossStrand":false,"outcomes":["Listen to a group discussion about choosing a class representative in the selected indigenous language and identify two accurate details without guessing.","Use taking turns, polite interruption and verbs in a culturally appropriate response about good decisions, listening to others and responsible community leadership, with guidance from a fluent speaker.","Present a short spoken exchange and respond respectfully to another speaker's question or correction."],"inquiry":["What makes a listener understand a message about leadership?","How do experienced speakers in our community express self-expression naturally?"],"experiences":["A fluent community-language speaker models a group discussion about choosing a class representative; pupils describe the central message before asking one question.","Pairs rehearse a short exchange using language-specific vocabulary confirmed by the teacher and compare expression, tone and courtesy."],"resources":"Fluent community-language recording, picture prompts and pair-speaking cards.","assessment":"Teacher observes attentive recall, authentic local-language vocabulary and respectful oral interaction, using a simple three-point checklist.","competencies":"Communication and collaboration; creativity; critical thinking; self-efficacy; cultural identity; digital literacy where permitted.","reviewStatus":"language_adaptation_required"},{"id":"09-RD","theme":9,"themeTitle":"Leadership","sourcePage":49,"strand":"Reading","title":"Leadership: Reading Comprehension: Poetry","focus":"Reading Comprehension: Poetry","focusDetail":"Poem features and responding to ideas","lessons":2,"crossStrand":false,"outcomes":["Read a simple poem about honesty and responsible leadership in the selected indigenous language, attending to poem features and responding to ideas.","Locate and explain two details from the reading and support an interpretation with words from the text.","Explain a new word, proverb or expression through context or confirmation with a fluent language user."],"inquiry":["How can a reader understand leadership from words and surrounding clues?","What does the text reveal about how this community uses language?"],"experiences":["Use a locally verified short text about good decisions, listening to others and responsible community leadership; learners mark familiar words, predict meaning and reread for accuracy.","Pairs discuss a comprehension question and practise correct pacing or interpretation with a fluent speaker's feedback."],"resources":"Original or licensed local-language passage, bilingual picture clues and reader's notebook.","assessment":"Reading aloud or assisted reading plus two text-based questions and a short explanation of a locally verified expression.","competencies":"Communication and collaboration; creativity; critical thinking; self-efficacy; cultural identity; digital literacy where permitted.","reviewStatus":"language_adaptation_required"},{"id":"09-WR","theme":9,"themeTitle":"Leadership","sourcePage":49,"strand":"Writing","title":"Leadership: Functional Writing: Instructions","focus":"Functional Writing: Instructions","focusDetail":"Clear steps, instruction charts and action verbs","lessons":2,"crossStrand":false,"outcomes":["Recognise the purpose and accepted spelling or writing conventions for functional writing: instructions in the chosen indigenous language.","Produce an original, age-appropriate written response about good decisions, listening to others and responsible community leadership that uses clear steps, instruction charts and action verbs.","Revise for local-language spelling, readable organisation and correct meaning with feedback from a fluent speaker."],"inquiry":["How can writing about leadership be made clearer for its intended reader?","Which writing conventions are used by fluent writers of this indigenous language?"],"experiences":["Observe a locally verified writing model about good decisions, listening to others and responsible community leadership; sort its useful features and plan a short response.","Draft, exchange careful feedback and revise a final version, following the chosen language's orthography rather than imported English spelling rules."],"resources":"Paper, writing strips and a language-specific, fluent-speaker-checked model.","assessment":"Short written product checked for purpose, clear organisation and language-specific orthography verified by a competent speaker.","competencies":"Communication and collaboration; creativity; critical thinking; self-efficacy; cultural identity; digital literacy where permitted.","reviewStatus":"language_adaptation_required"},{"id":"10-SH","theme":10,"themeTitle":"Cross-strand Skills Showcase","sourcePage":54,"strand":"Cross-strand showcase","title":"Indigenous Languages: Showcase of spoken, reading and writing skills","focus":"Present, read and share work","focusDetail":"Community-validated performance, reading and writing portfolio","lessons":6,"crossStrand":true,"outcomes":["Prepare a short spoken performance, reading or story based on an Indigenous Languages theme with culturally respectful language choices.","Present a selected writing sample and discuss how feedback from a fluent speaker improved its clarity and accuracy.","Listen to and respond constructively to peers, recognising different language varieties and the value of each community."],"inquiry":["How do spoken, read and written expressions help preserve our language?","How can learners present cultural knowledge with respect and accuracy?"],"experiences":["Pairs assemble a small portfolio of revised written pieces, recitations and reading responses and select samples for an in-class exhibition.","Invite fluent speakers to review vocabulary, spelling and cultural suitability; learners reflect on what they improved."],"resources":"Pupil portfolio, performance rubric, original reading texts and invited community-language reviewers.","assessment":"Performance and portfolio rubric covering communication, accuracy confirmed by fluent speakers and respect for community knowledge.","competencies":"Communication and collaboration; creativity; cultural identity; citizenship; self-efficacy.","reviewStatus":"language_adaptation_required"}]$vs_g4_il$::jsonb) unit;

do $preflight$
begin
 if (select count(*) from _vs_g4_il_catalog)<>28
    or (select count(distinct unit->>'theme') from _vs_g4_il_catalog where (unit->>'crossStrand')::boolean=false)<>9
    or (select count(distinct unit->>'strand') from _vs_g4_il_catalog where (unit->>'crossStrand')::boolean=false)<>3
    or (select count(*) from _vs_g4_il_catalog where (unit->>'crossStrand')::boolean=true)<>1
    or (select sum((unit->>'lessons')::int) from _vs_g4_il_catalog)<>60
    or (select sum(jsonb_array_length(unit->'outcomes')) from _vs_g4_il_catalog)<>84
 then raise exception 'GRADE4_INDIGENOUS_SOURCE_COVERAGE_FAILED'; end if;
 if (select count(*) from public.subjects
      where name='Indigenous Languages' and school_id is null and global_subject_id is null)<>1
 then raise exception 'GRADE4_INDIGENOUS_GLOBAL_SUBJECT_REQUIRED'; end if;
 if exists(select 1 from _vs_g4_il_catalog t
   join public.subjects sub on sub.name='Indigenous Languages' and sub.school_id is null and sub.global_subject_id is null
   join public.cbc_strands s on s.subject_id=sub.id and s.grade='Grade 4'
      and s.name=t.unit->>'strand' and s.sub_strand=t.unit->>'title'
   where s.source_ref is not null and s.source_ref<>t.source_ref)
 then raise exception 'GRADE4_INDIGENOUS_EXISTING_SOURCE_CONFLICT'; end if;
end;$preflight$;

insert into public.cbc_strands
 (subject_id,grade,name,sub_strand,strand_order,sub_strand_order,
  key_inquiry_questions,suggested_experiences,source_ref)
select sub.id,'Grade 4',t.unit->>'strand',t.unit->>'title',
 case t.unit->>'strand'
  when 'Listening and Speaking' then 1 when 'Reading' then 2
  when 'Writing' then 3 else 4 end,
 (t.unit->>'theme')::integer,
 array(select jsonb_array_elements_text(t.unit->'inquiry')),
 array(select jsonb_array_elements_text(t.unit->'experiences')),
 t.source_ref
from _vs_g4_il_catalog t
join public.subjects sub on sub.name='Indigenous Languages' and sub.school_id is null and sub.global_subject_id is null
on conflict(subject_id,grade,name,sub_strand) do nothing;

insert into public.grade4_indigenous_reader_bindings
 (source_ref,sub_strand_id,source_url,source_version,key_inquiry_questions,suggested_experiences,localization_status)
select t.source_ref,s.id,'https://kicd.ac.ke/wp-content/uploads/2024/10/GRADE-4-INDIGENOUS-LANGUAGE-DESIGN-Revised.pdf','KICD Grade 4 Indigenous Languages, revised 2024',
 array(select jsonb_array_elements_text(t.unit->'inquiry')),
 array(select jsonb_array_elements_text(t.unit->'experiences')),
 'language_adaptation_required'
from _vs_g4_il_catalog t
join public.subjects sub on sub.name='Indigenous Languages' and sub.school_id is null and sub.global_subject_id is null
join public.cbc_strands s on s.subject_id=sub.id and s.grade='Grade 4'
   and s.name=t.unit->>'strand' and s.sub_strand=t.unit->>'title'
on conflict(source_ref) do nothing;

insert into public.curriculum_unit_guidance
 (sub_strand_id,suggested_lessons,learning_resources,assessment_methods,competencies,safety_notes,content_status)
select b.sub_strand_id,(t.unit->>'lessons')::int,
 t.unit->>'resources',t.unit->>'assessment',t.unit->>'competencies',
 'Language-specific vocabulary, spelling and cultural contexts must be reviewed by a fluent community member. Never present English planning guidance as a validated translation or collected community story.','active'
from _vs_g4_il_catalog t
join public.grade4_indigenous_reader_bindings b on b.source_ref=t.source_ref
on conflict(sub_strand_id) do nothing;

insert into public.curriculum_learning_outcomes
 (sub_strand_id,outcome_text,outcome_code,source_type,source_ref,status)
select b.sub_strand_id,o.text,
 'VS-G4-IL-'||(t.unit->>'id')||'-'||lpad(o.ordinality::text,2,'0'),
 'creator_claimed',t.source_ref||'/'||o.ordinality,'active'
from _vs_g4_il_catalog t
join public.grade4_indigenous_reader_bindings b on b.source_ref=t.source_ref
cross join lateral jsonb_array_elements_text(t.unit->'outcomes') with ordinality as o(text,ordinality)
where not exists (select 1 from public.curriculum_learning_outcomes v
  where v.source_ref=t.source_ref||'/'||o.ordinality);

drop policy if exists grade4_indigenous_guidance_read on public.curriculum_unit_guidance;
create policy grade4_indigenous_guidance_read on public.curriculum_unit_guidance
 for select to authenticated using(content_status='active' and exists(
  select 1 from public.grade4_indigenous_reader_bindings b
  where b.sub_strand_id=curriculum_unit_guidance.sub_strand_id and b.status='active'));

drop policy if exists grade4_indigenous_outcomes_read on public.curriculum_learning_outcomes;
create policy grade4_indigenous_outcomes_read on public.curriculum_learning_outcomes
 for select to authenticated using(status='active' and source_type='creator_claimed'
  and created_by is null and source_ref like 'VS-CUR-G04-IL-2026#%');

do $verify$
begin
 if (select count(*) from public.grade4_indigenous_reader_bindings where status='active')<>28
   or (select count(*) from public.curriculum_learning_outcomes where status='active' and source_ref like 'VS-CUR-G04-IL-2026#%')<>84
   or (select coalesce(sum(g.suggested_lessons),0)
      from public.grade4_indigenous_reader_bindings b
      join public.curriculum_unit_guidance g on g.sub_strand_id=b.sub_strand_id
      where b.status='active' and g.content_status='active')<>60
 then raise exception 'GRADE4_INDIGENOUS_PERSISTENCE_INCOMPLETE'; end if;
end;$verify$;

-- Reuse the existing security-invoker, teacher/assignment/term-checked Scheme saver.
-- Singular 'Indigenous Language' legacy subject identity is accepted only as an
-- exact alias for the Grade 4 source-bound Indigenous Languages curriculum.
-- No other mismatch, grade or teacher authorization is relaxed.
do $patch$
declare
 definition text;
 old_gate text := $target$  if not found then raise exception 'SCHEME_CURRICULUM_SUBSTRAND_NOT_FOUND'; end if;$target$;
 new_gate text := $replacement$  if not found then
    select * into v_unit from public.cbc_strands s
    where s.id=p_sub_strand_id and s.grade='Grade 4'
      and exists(select 1 from public.grade4_indigenous_reader_bindings b
                 where b.sub_strand_id=s.id and b.status='active');
  end if;
  if not found then raise exception 'SCHEME_CURRICULUM_SUBSTRAND_NOT_FOUND'; end if;$replacement$;
 old_lookup text := $target$  if v_reader_ref is null then
    v_reader_ref:=v_unit.source_ref;$target$;
 new_lookup text := $replacement$  if v_reader_ref is null then
    select b.source_ref,b.key_inquiry_questions,b.suggested_experiences
      into v_reader_ref,v_reader_inquiry,v_reader_experiences
    from public.grade4_indigenous_reader_bindings b
    where b.sub_strand_id=v_unit.id and b.status='active';
  end if;
  if v_reader_ref is null then
    v_reader_ref:=v_unit.source_ref;$replacement$;
 old_identity text := $target$  if v_global_subject is distinct from v_unit.subject_id
    or lower(btrim(coalesce(v_grade,'')))<>lower(v_unit.grade)
  then raise exception 'SCHEME_CURRICULUM_IDENTITY_MISMATCH'; end if;$target$;
 new_identity text := $replacement$  if (v_global_subject is distinct from v_unit.subject_id
       and not (
         v_unit.grade='Grade 4'
         and exists(select 1 from public.grade4_indigenous_reader_bindings b
                     where b.sub_strand_id=v_unit.id and b.status='active')
         and exists(select 1 from public.subjects a where a.id=v_global_subject
                     and a.name='Indigenous Language' and a.school_id is null)
         and exists(select 1 from public.subjects c where c.id=v_unit.subject_id
                     and c.name='Indigenous Languages' and c.school_id is null)
       ))
    or lower(btrim(coalesce(v_grade,'')))<>lower(v_unit.grade)
  then raise exception 'SCHEME_CURRICULUM_IDENTITY_MISMATCH'; end if;$replacement$;
begin
 definition:=pg_get_functiondef('public.commit_mapped_scheme_lesson(uuid,uuid,uuid,integer,uuid,uuid[])'::regprocedure);
 if definition ilike '%security definer%' then raise exception 'SCHEME_INVOKER_AUTHORITY_REQUIRED'; end if;
 if position(old_gate in definition)=0 or position(old_lookup in definition)=0 or position(old_identity in definition)=0
 then raise exception 'SCHEME_RPC_VERSION_INCOMPATIBLE_WITH_GRADE4_INDIGENOUS'; end if;
 definition:=replace(replace(replace(definition,old_gate,new_gate),old_lookup,new_lookup),old_identity,new_identity);
 execute definition;
end;$patch$;
revoke all on function public.commit_mapped_scheme_lesson(uuid,uuid,uuid,integer,uuid,uuid[]) from public,anon;
grant execute on function public.commit_mapped_scheme_lesson(uuid,uuid,uuid,integer,uuid,uuid[]) to authenticated;
commit;
